<template><span class="inline-flex rounded-full px-3 py-1 text-xs font-bold" :class="classes">{{ status }}</span></template>
<script>export default { props: { status: String }, computed: { classes() { const s = this.status || ''; if (s.includes('Cancelled') || s.includes('Delayed') || s === 'Low') return 'bg-red-50 text-red-700'; if (s.includes('Delivered') || s.includes('Approved') || s === 'Healthy') return 'bg-green-50 text-green-700'; if (s.includes('Transit') || s.includes('Partial')) return 'bg-blue-50 text-blue-700'; return 'bg-yellow-50 text-yellow-800'; } } }</script>